/**
 * ADR-KEY-01: the `SECRET_KEY` ring and the rotation command (KR-1..KR-14). Every key is generated by the test.
 */
import { expect } from 'chai';
import { randomBytes } from 'node:crypto';
import { InMemoryDataKeyStore } from '../../../src/modules/agent-harness/adapters/in-memory-data-key-store';
import {
  HkdfKeyEncryptionKey,
  RingKeyEncryptionKey,
} from '../../../src/modules/agent-harness/adapters/crypto/hkdf-key-encryption-key';
import { OrgDataKeys } from '../../../src/modules/agent-harness/application/org-data-keys';
import {
  RotationLockLost,
  SecretKeyRotation,
  emptyReport,
  type RotationStep,
  type StepContext,
  type StepReport,
} from '../../../src/modules/agent-harness/application/secret-key-rotation';
import {
  ConfigStoreReencryptStep,
  DataKeyRewrapStep,
  OAuthClientSecretStep,
  type ClientSecretStore,
  type ForOrg,
  type RotationKeyValueStore,
} from '../../../src/modules/agent-harness/application/secret-key-rotation-steps';
import { HmacRunKeyDigest } from '../../../src/modules/agent-harness/domain/run-key-digest';
import type { LeaderLease } from '../../../src/modules/agent-harness/ports/leader-lease';
import { EncryptionService } from '../../../src/libs/encryptor/encryptor';
import {
  hashedRing,
  hashedSecret,
  secretKeyRing,
  SecretKeyRingError,
} from '../../../src/libs/encryptor/secret-key-ring';
import { SealedContentError } from '../../../src/modules/agent-harness/domain/errors';

const ALG = 'aes-256-gcm';
const ORG_A = 'org-a';
const ORG_B = 'org-b';
const secret = (): string => randomBytes(32).toString('hex');

const kek = (raw: string): HkdfKeyEncryptionKey =>
  new HkdfKeyEncryptionKey(() => Buffer.from(hashedSecret(raw), 'hex'));
const ringKek = (...raws: string[]): RingKeyEncryptionKey =>
  new RingKeyEncryptionKey(() => raws.map(kek));
const cipherOf = (...raws: string[]): EncryptionService =>
  EncryptionService.withRing(ALG, raws.map(hashedSecret) as [string, ...string[]]);
const sameOrg: ForOrg = (_orgId, fn) => fn();

class MemoryLease implements LeaderLease {
  holder: string | null = null;
  stolen = false;
  async tryAcquire(_name: string, holder: string): Promise<boolean> {
    if (this.stolen) return false;
    this.holder ??= holder;
    return this.holder === holder;
  }
  async release(_name: string, holder: string): Promise<void> {
    if (this.holder === holder) this.holder = null;
  }
}

/** Every acquire wins: two runs that overlap anyway (one paused past its lease). */
class OpenLease implements LeaderLease {
  async tryAcquire(): Promise<boolean> {
    return true;
  }
  async release(): Promise<void> {}
}

class MemoryKv implements RotationKeyValueStore {
  readonly values = new Map<string, string>();
  /** Called before each compare-and-set: a concurrent writer. */
  beforeCas: ((key: string) => void) | null = null;
  async getAllKeys(): Promise<string[]> {
    return [...this.values.keys()];
  }
  async get<T>(key: string): Promise<T | null> {
    return (this.values.get(key) ?? null) as T | null;
  }
  async compareAndSet<T>(key: string, expected: T | null, next: T): Promise<boolean> {
    this.beforeCas?.(key);
    if ((this.values.get(key) ?? null) !== expected) return false;
    this.values.set(key, next as unknown as string);
    return true;
  }
}

class MemoryApps implements ClientSecretStore {
  readonly apps = new Map<string, { orgId: string; secret: string }>();
  async listClientSecrets(orgId: string): Promise<Array<{ id: string; clientSecretEncrypted: string }>> {
    return [...this.apps.entries()]
      .filter(([, app]) => app.orgId === orgId)
      .map(([id, app]) => ({ id, clientSecretEncrypted: app.secret }));
  }
  async replaceClientSecret(orgId: string, id: string, expected: string, next: string): Promise<boolean> {
    const app = this.apps.get(id);
    if (app?.orgId !== orgId || app.secret !== expected) return false;
    app.secret = next;
    return true;
  }
}

/** The egress step's shape over in-memory records sealed under one of the keys. */
class MemoryEgress implements RotationStep {
  readonly name = 'egress-state';
  records = new Map<string, 'current' | 'previous' | 'unknown'>();
  draining = 0;
  async run(context: StepContext): Promise<StepReport> {
    const report = emptyReport(this.name);
    for (const [key, under] of this.records) {
      context.checkpoint();
      report.total += 1;
      if (under === 'unknown') report.unreadable += 1;
      else if (under === 'current') report.current += 1;
      else if (context.apply) {
        this.records.set(key, 'current');
        report.moved += 1;
        report.current += 1;
      } else report.previous += 1;
    }
    report.draining = this.draining;
    return report;
  }
}

/** A step that dies once, after `after` items of the inner step have been handled. */
class Crashing implements RotationStep {
  readonly name: string;
  armed = true;
  constructor(
    private readonly inner: RotationStep,
    private readonly after: number,
  ) {
    this.name = inner.name;
  }
  run(context: StepContext): Promise<StepReport> {
    if (!context.apply || !this.armed) return this.inner.run(context);
    let seen = 0;
    return this.inner.run({
      ...context,
      checkpoint: () => {
        context.checkpoint();
        if (seen++ >= this.after) {
          this.armed = false;
          throw new Error('crash');
        }
      },
    });
  }
}

interface World {
  oldKey: string;
  newKey: string;
  store: InMemoryDataKeyStore;
  kv: MemoryKv;
  apps: MemoryApps;
  egress: MemoryEgress;
  steps(): RotationStep[];
}

/** A deployment whose data was all written under `oldKey`, now running with `newKey` + `oldKey` as previous. */
async function world(): Promise<World> {
  const oldKey = secret();
  const newKey = secret();
  const store = new InMemoryDataKeyStore();
  for (const orgId of [ORG_A, ORG_B]) {
    const keys = new OrgDataKeys({ store, kek: kek(oldKey) });
    await keys.active(orgId);
    await keys.rotate(orgId);
  }
  const old = cipherOf(oldKey);
  const kv = new MemoryKv();
  kv.values.set('/services/a', old.encrypt('{"token":"a"}'));
  kv.values.set('/services/python', JSON.stringify(old.encrypt('"py"')));
  kv.values.set('/services/doc', JSON.stringify({ name: 'x', secret: old.encrypt('s'), list: [old.encrypt('t')] }));
  kv.values.set('/services/plain', '{"endpoint":"http://x"}');
  const apps = new MemoryApps();
  apps.apps.set('app-1', { orgId: ORG_A, secret: old.encrypt('client-secret-1') });
  apps.apps.set('app-2', { orgId: ORG_B, secret: old.encrypt('client-secret-2') });
  const egress = new MemoryEgress();
  egress.records.set('binding/s1', 'previous');
  egress.records.set('authority', 'previous');
  const cipher = cipherOf(newKey, oldKey);
  return {
    oldKey,
    newKey,
    store,
    kv,
    apps,
    egress,
    steps: () => [
      new DataKeyRewrapStep(store, ringKek(newKey, oldKey), sameOrg),
      egress,
      new ConfigStoreReencryptStep(kv, cipher),
      new OAuthClientSecretStep(apps, async () => [ORG_A, ORG_B], cipher, sameOrg),
    ],
  };
}

const rotation = (
  steps: RotationStep[],
  over: Partial<ConstructorParameters<typeof SecretKeyRotation>[0]> = {},
): SecretKeyRotation =>
  new SecretKeyRotation({
    steps,
    ring: { other: 'previous' },
    lease: new MemoryLease(),
    holder: 'operator-1',
    ...over,
  });

const total = (steps: StepReport[], field: keyof Omit<StepReport, 'step'>): number =>
  steps.reduce((sum, step) => sum + step[field], 0);

/** Everything the deployment holds opens under the new key alone. */
async function allUnderNewKey(w: World): Promise<void> {
  const only = cipherOf(w.newKey);
  const onlyKek = kek(w.newKey);
  for (const orgId of [ORG_A, ORG_B]) {
    for (const key of await w.store.list(orgId)) {
      expect(key.kekId).to.equal(onlyKek.id);
      await onlyKek.unwrap(key.wrapped, { orgId, kid: key.kid, version: key.version });
    }
  }
  expect(only.decrypt(w.kv.values.get('/services/a'))).to.equal('{"token":"a"}');
  expect(only.decrypt(JSON.parse(w.kv.values.get('/services/python') as string) as string)).to.equal('"py"');
  const doc = JSON.parse(w.kv.values.get('/services/doc') as string) as { name: string; secret: string; list: string[] };
  expect(doc.name).to.equal('x');
  expect(only.decrypt(doc.secret)).to.equal('s');
  expect(only.decrypt(doc.list[0])).to.equal('t');
  expect(w.kv.values.get('/services/plain')).to.equal('{"endpoint":"http://x"}');
  expect(only.decrypt(w.apps.apps.get('app-1')?.secret)).to.equal('client-secret-1');
  expect(only.decrypt(w.apps.apps.get('app-2')?.secret)).to.equal('client-secret-2');
  expect([...w.egress.records.values()].every((under) => under === 'current')).to.equal(true);
}

describe('ADR-KEY-01: rotating SECRET_KEY', () => {
  describe('the ring (KR-1)', () => {
    it('KR-1: SECRET_KEY alone, or with one other key; every misconfiguration fails closed and names no value', () => {
      const current = secret();
      const other = secret();
      expect(secretKeyRing({ PIPESHUB_HARDENED: 'true', SECRET_KEY: current })).to.deep.equal({ current, other: null });
      expect(secretKeyRing({ PIPESHUB_HARDENED: 'true', SECRET_KEY: current, SECRET_KEY_PREVIOUS: other }).other).to.deep.equal({
        role: 'previous',
        secret: other,
      });
      expect(secretKeyRing({ PIPESHUB_HARDENED: 'true', SECRET_KEY: current, SECRET_KEY_NEXT: other }).other?.role).to.equal('next');
      const refused = (env: Record<string, string>): string => {
        try {
          secretKeyRing(env);
        } catch (error) {
          expect(error).to.be.instanceOf(SecretKeyRingError);
          return (error as Error).message;
        }
        throw new Error('accepted');
      };
      expect(refused({})).to.equal('SECRET_KEY environment variable is required');
      expect(refused({ SECRET_KEY: current, SECRET_KEY_PREVIOUS: other, SECRET_KEY_NEXT: secret() })).to.match(/never both/);
      const same = refused({ SECRET_KEY: current, SECRET_KEY_PREVIOUS: current });
      expect(same).to.equal('SECRET_KEY_PREVIOUS is the same as SECRET_KEY: a rotation needs a new key');
      expect(refused({ SECRET_KEY: current, SECRET_KEY_NEXT: current })).to.match(/^SECRET_KEY_NEXT is the same/);
      expect(same).not.to.include(current);
      expect(hashedRing(secretKeyRing({ PIPESHUB_HARDENED: 'true', SECRET_KEY: current, SECRET_KEY_PREVIOUS: other }))).to.deep.equal([
        hashedSecret(current),
        hashedSecret(other),
      ]);
    });
  });

  describe('readers meet data under the previous key (KR-2..KR-5)', () => {
    it('KR-2: the platform cipher opens a value of either key, says which, and writes under the current one', () => {
      const oldKey = secret();
      const newKey = secret();
      const sealed = cipherOf(oldKey).encrypt('value');
      const ring = cipherOf(newKey, oldKey);
      expect(ring.decryptDetailed(sealed)).to.deep.equal({ plaintext: 'value', current: false });
      const rewritten = ring.encrypt('value');
      expect(ring.decryptDetailed(rewritten)).to.deep.equal({ plaintext: 'value', current: true });
      expect(() => cipherOf(oldKey).decrypt(rewritten)).to.throw(/Decryption failed/);
      expect(() => cipherOf(secret()).decrypt(sealed)).to.throw(/Decryption failed/);
    });

    it('KR-3: the process-wide cipher takes the ring only for the deployment\'s own key', () => {
      const saved = { ...process.env };
      const holder = EncryptionService as unknown as { instance?: EncryptionService };
      const before = holder.instance;
      try {
        const oldKey = secret();
        const newKey = secret();
        process.env.SECRET_KEY = newKey;
        process.env.SECRET_KEY_PREVIOUS = oldKey;
        delete process.env.SECRET_KEY_NEXT;
        holder.instance = undefined;
        const platform = EncryptionService.getInstance(ALG, hashedSecret(newKey));
        expect(platform.decryptDetailed(cipherOf(oldKey).encrypt('x')).current).to.equal(false);
        holder.instance = undefined;
        const other = EncryptionService.getInstance(ALG, hashedSecret(secret()));
        expect(() => other.decrypt(cipherOf(oldKey).encrypt('x'))).to.throw(/Decryption failed/);
        holder.instance = undefined;
        process.env.SECRET_KEY_NEXT = newKey;
        // A broken ring here: the caller's key reads alone (the services refuse the ring before this).
        expect(() => EncryptionService.getInstance(ALG, hashedSecret(newKey)).decrypt(cipherOf(oldKey).encrypt('x'))).to.throw();
      } finally {
        process.env = saved;
        holder.instance = before;
      }
    });

    it('KR-4: an org data key wrapped under the previous KEK opens through the ring; one under neither fails closed', async () => {
      const oldKey = secret();
      const newKey = secret();
      const store = new InMemoryDataKeyStore();
      const before = new OrgDataKeys({ store, kek: kek(oldKey) });
      const sealedUnder = await before.active(ORG_A);
      const ring = ringKek(newKey, oldKey);
      expect(ring.ids).to.deep.equal([kek(newKey).id, kek(oldKey).id]);
      const after = new OrgDataKeys({ store, kek: ring });
      expect((await after.byRef(ORG_A, sealedUnder)).key.equals(sealedUnder.key)).to.equal(true);
      // New keys are wrapped under the current KEK only.
      await after.rotate(ORG_A);
      const [, newest] = await store.list(ORG_A);
      expect(newest?.kekId).to.equal(ring.id);
      const stranger = new OrgDataKeys({ store, kek: ringKek(secret(), secret()) });
      const error = await stranger.byRef(ORG_A, sealedUnder).catch((e: unknown) => e);
      expect(error).to.be.instanceOf(SealedContentError);
      expect((error as SealedContentError).reason).to.equal('unwrap_failed');
      expect((error as Error).message).to.match(/neither SECRET_KEY nor SECRET_KEY_PREVIOUS/);
      // Without a kekId the ring's current key is tried.
      const unnamed = await ring.unwrap(newest!.wrapped, { orgId: ORG_A, kid: newest!.kid, version: newest!.version });
      expect(unnamed.length).to.equal(32);
    });

    it('KR-5: a run-key digest made under the previous key still matches, compared in constant time', () => {
      const oldKey = randomBytes(32);
      const newKey = randomBytes(32);
      const before = new HmacRunKeyDigest(() => oldKey).digest(ORG_A, 'turn:1');
      const ring = new HmacRunKeyDigest(() => newKey, () => [oldKey]);
      expect(ring.digest(ORG_A, 'turn:1')).not.to.equal(before);
      expect(ring.matches(ORG_A, 'turn:1', before)).to.equal(true);
      expect(ring.matches(ORG_A, 'turn:1', ring.digest(ORG_A, 'turn:1'))).to.equal(true);
      expect(ring.matches(ORG_A, 'turn:2', before)).to.equal(false);
      expect(ring.matches(ORG_B, 'turn:1', before)).to.equal(false);
      expect(ring.matches(ORG_A, 'turn:1', 'hk1:short')).to.equal(false);
      expect(new HmacRunKeyDigest(() => newKey).matches(ORG_A, 'turn:1', before)).to.equal(false);
    });

    it('KR-17: a mixed fleet mid-restart: a replica before the switch (old + NEXT) and one after it (new + PREVIOUS) read each other', async () => {
      const oldKey = secret();
      const newKey = secret();
      const before = { cipher: cipherOf(oldKey, newKey), kek: ringKek(oldKey, newKey) };
      const after = { cipher: cipherOf(newKey, oldKey), kek: ringKek(newKey, oldKey) };
      expect(after.cipher.decrypt(before.cipher.encrypt('a'))).to.equal('a');
      expect(before.cipher.decrypt(after.cipher.encrypt('b'))).to.equal('b');
      const store = new InMemoryDataKeyStore();
      const writtenBefore = await new OrgDataKeys({ store, kek: before.kek }).active(ORG_A);
      const writtenAfter = await new OrgDataKeys({ store, kek: after.kek }).active(ORG_B);
      expect((await new OrgDataKeys({ store, kek: after.kek }).byRef(ORG_A, writtenBefore)).key.equals(writtenBefore.key)).to.equal(true);
      expect((await new OrgDataKeys({ store, kek: before.kek }).byRef(ORG_B, writtenAfter)).key.equals(writtenAfter.key)).to.equal(true);
      // A build from before the ring reads only its one key: it must not run during the switch.
      expect(() => cipherOf(oldKey).decrypt(after.cipher.encrypt('c'))).to.throw(/Decryption failed/);
    });
  });

  describe('the command (KR-6..KR-14)', () => {
    it('KR-6: dry-run counts and writes nothing; rotate moves everything; verify and retire then pass', async () => {
      const w = await world();
      const snapshot = JSON.stringify([...w.kv.values]);
      const progress: StepReport[] = [];
      const dry = await rotation(w.steps(), { onProgress: (r) => progress.push(r) }).run('dry-run');
      expect(dry.ok).to.equal(true);
      expect(dry.steps.map((s) => [s.step, s.previous])).to.deep.equal([
        ['data-keys', 4],
        ['egress-state', 2],
        ['config-store', 3],
        ['oauth-client-secrets', 2],
      ]);
      expect(JSON.stringify([...w.kv.values])).to.equal(snapshot);
      expect(progress.length).to.be.greaterThan(0);
      expect((await rotation(w.steps()).run('verify')).ok).to.equal(false);
      const retireEarly = await rotation(w.steps()).run('retire');
      expect(retireEarly.ok).to.equal(false);
      expect(retireEarly.refused).to.match(/cannot be retired yet: 11 item\(s\) are still under SECRET_KEY_PREVIOUS/);

      const done = await rotation(w.steps()).run('rotate');
      expect(done.ok, done.refused ?? '').to.equal(true);
      expect(total(done.steps, 'moved')).to.equal(11);
      expect(total(done.steps, 'previous')).to.equal(0);
      await allUnderNewKey(w);
      expect((await rotation(w.steps()).run('verify')).ok).to.equal(true);
      const retire = await rotation(w.steps()).run('retire');
      expect(retire.ok).to.equal(true);
      // A second rotate finds nothing to move.
      expect(total((await rotation(w.steps()).run('rotate')).steps, 'moved')).to.equal(0);
    });

    for (const [index, name] of ['data-keys', 'egress-state', 'config-store', 'oauth-client-secrets'].entries()) {
      for (const after of [0, 1]) {
        it(`KR-7: a crash in ${name} after ${String(after)} item(s), then a resume, moves everything once`, async () => {
          const w = await world();
          const steps = w.steps();
          steps[index] = new Crashing(steps[index] as RotationStep, after);
          const lease = new MemoryLease();
          const crashed = await rotation(steps, { lease }).run('rotate').catch((e: unknown) => e);
          expect((crashed as Error).message).to.equal('crash');
          // The crashed run released its lock; what it moved stays moved.
          expect(lease.holder).to.equal(null);
          const resumed = await rotation(steps, { lease }).run('rotate');
          expect(resumed.ok, resumed.refused ?? '').to.equal(true);
          await allUnderNewKey(w);
        });
      }
    }

    it('KR-8: a crash between two steps (after one finished), then a resume', async () => {
      const w = await world();
      const steps = w.steps();
      steps[2] = new Crashing(steps[2] as RotationStep, 0);
      await rotation(steps).run('rotate').catch(() => undefined);
      const halfway = await rotation(w.steps()).run('dry-run');
      expect(halfway.steps.map((s) => s.previous)).to.deep.equal([0, 0, 3, 2]);
      expect((await rotation(steps).run('rotate')).ok).to.equal(true);
      await allUnderNewKey(w);
    });

    it('KR-9: a second operator is refused while the first holds the lock', async () => {
      const w = await world();
      const lease = new MemoryLease();
      let release!: () => void;
      const gate = new Promise<void>((resolve) => {
        release = resolve;
      });
      const slow: RotationStep = {
        name: 'slow',
        run: async (context) => {
          if (context.apply) await gate;
          return emptyReport('slow');
        },
      };
      const first = rotation([slow, ...w.steps()], { lease, holder: 'operator-1' }).run('rotate');
      await new Promise((resolve) => setImmediate(resolve));
      for (const mode of ['rotate', 'retire'] as const) {
        const second = await rotation(w.steps(), { lease, holder: 'operator-2' }).run(mode);
        expect(second.ok).to.equal(false);
        expect(second.refused).to.match(/another run of the rotation holds the lock/);
        expect(second.steps).to.deep.equal([]);
      }
      release();
      expect((await first).ok).to.equal(true);
      await allUnderNewKey(w);
    });

    it('KR-10: two runs that overlap anyway (a lapsed lease) both finish and every item is moved once, by compare-and-set', async () => {
      const w = await world();
      const [one, two] = await Promise.all([
        rotation(w.steps(), { lease: new OpenLease(), holder: 'a' }).run('rotate'),
        rotation(w.steps(), { lease: new OpenLease(), holder: 'b' }).run('rotate'),
      ]);
      expect(one.ok && two.ok).to.equal(true);
      await allUnderNewKey(w);
    });

    it('KR-11: a run that loses its lock stops at its next item', async () => {
      const w = await world();
      const lease = new MemoryLease();
      const steps = w.steps();
      const thief: RotationStep = {
        name: 'thief',
        run: async (context) => {
          if (context.apply) {
            lease.stolen = true;
            await new Promise((resolve) => setTimeout(resolve, 15));
          }
          context.checkpoint();
          return emptyReport('thief');
        },
      };
      const error = await rotation([thief, ...steps], { lease, renewEveryMs: 5 })
        .run('rotate')
        .catch((e: unknown) => e);
      expect(error).to.be.instanceOf(RotationLockLost);
    });

    it('KR-12: a wrong previous key fails closed before anything moves; --accept-unreadable must name the exact count', async () => {
      const w = await world();
      const wrong = secret();
      const cipher = cipherOf(w.newKey, wrong);
      const steps = [
        new DataKeyRewrapStep(w.store, ringKek(w.newKey, wrong), sameOrg),
        new ConfigStoreReencryptStep(w.kv, cipher),
        new OAuthClientSecretStep(w.apps, async () => [ORG_A, ORG_B], cipher, sameOrg),
      ];
      const snapshot = JSON.stringify([...w.kv.values]);
      const refused = await rotation(steps).run('rotate');
      expect(refused.ok).to.equal(false);
      expect(refused.refused).to.match(
        /^9 item\(s\) open under neither SECRET_KEY nor SECRET_KEY_PREVIOUS: check that SECRET_KEY_PREVIOUS/,
      );
      expect(refused.refused).to.include('--accept-unreadable 9');
      expect(refused.refused).not.to.include(wrong);
      expect(JSON.stringify([...w.kv.values])).to.equal(snapshot);
      expect((await rotation(steps, { acceptUnreadable: 8 }).run('rotate')).ok).to.equal(false);
      expect((await rotation(steps).run('retire')).refused).to.match(/cannot be retired yet: 9 item\(s\) open under neither/);
      // Acknowledged: the run goes ahead, and still moves nothing it cannot open.
      const accepted = await rotation(steps, { acceptUnreadable: 9 }).run('rotate');
      expect(accepted.refused).to.equal(null);
      expect(total(accepted.steps, 'moved')).to.equal(0);
      expect(JSON.stringify([...w.kv.values])).to.equal(snapshot);
    });

    it('KR-13: a missing previous key, or a switch not finished, refuses rotate and retire', async () => {
      const w = await world();
      const missing = await rotation(w.steps(), { ring: { other: null } }).run('rotate');
      expect(missing.refused).to.match(/^SECRET_KEY_PREVIOUS is not set/);
      for (const mode of ['rotate', 'retire'] as const) {
        const next = await rotation(w.steps(), { ring: { other: 'next' } }).run(mode);
        expect(next.ok).to.equal(false);
        expect(next.refused).to.match(/^SECRET_KEY_NEXT is set: finish the switch first/);
      }
      // After SECRET_KEY_PREVIOUS is removed, data still under it reads as unreadable: retire is refused.
      const cipher = cipherOf(w.newKey);
      const after = await rotation(
        [new ConfigStoreReencryptStep(w.kv, cipher), new DataKeyRewrapStep(w.store, ringKek(w.newKey), sameOrg)],
        { ring: { other: null } },
      ).run('retire');
      expect(after.ok).to.equal(false);
      expect(after.refused).to.match(/open under neither/);
    });

    it('KR-14: retire waits for draining sandbox routes; a concurrent config write is read again, never overwritten', async () => {
      const w = await world();
      w.egress.draining = 2;
      let writes = 0;
      w.kv.beforeCas = (key) => {
        // Someone saves the setting again (under the current key) while the rotation reads it.
        if (key === '/services/a' && writes++ === 0) w.kv.values.set('/services/a', cipherOf(w.newKey).encrypt('{"token":"edited"}'));
      };
      const done = await rotation(w.steps()).run('rotate');
      expect(done.ok).to.equal(true);
      expect(cipherOf(w.newKey).decrypt(w.kv.values.get('/services/a'))).to.equal('{"token":"edited"}');
      const retire = await rotation(w.steps()).run('retire');
      expect(retire.ok).to.equal(false);
      expect(retire.refused).to.match(/2 running sandbox route\(s\) still hold a credential sealed under SECRET_KEY_PREVIOUS/);
      w.egress.draining = 0;
      expect((await rotation(w.steps()).run('retire')).ok).to.equal(true);
    });

    it('KR-15: a config value written on every attempt is left as it is and counted for the final check', async () => {
      const w = await world();
      const old = cipherOf(w.oldKey);
      w.kv.beforeCas = (key) => {
        if (key === '/services/a') w.kv.values.set(key, old.encrypt(randomBytes(4).toString('hex')));
      };
      const step = new ConfigStoreReencryptStep(w.kv, cipherOf(w.newKey, w.oldKey));
      const report = await step.run({ apply: true, checkpoint: () => undefined, progress: () => undefined });
      expect(report.previous).to.equal(1);
      expect(report.moved).to.equal(2);
    });

    it('KR-16: an OAuth secret changed between read and write is counted, not overwritten; a store with a stale wrap loses', async () => {
      const w = await world();
      const apps = w.apps;
      const original = apps.replaceClientSecret.bind(apps);
      apps.replaceClientSecret = async (orgId, id, expected, next) => {
        if (id === 'app-1') apps.apps.get('app-1')!.secret = cipherOf(w.newKey).encrypt('regenerated');
        return original(orgId, id, expected, next);
      };
      const step = new OAuthClientSecretStep(apps, async () => [ORG_A, ORG_B], cipherOf(w.newKey, w.oldKey), sameOrg);
      const report = await step.run({ apply: true, checkpoint: () => undefined, progress: () => undefined });
      expect(report).to.include({ moved: 1, previous: 1 });
      expect(cipherOf(w.newKey).decrypt(apps.apps.get('app-1')?.secret)).to.equal('regenerated');
      // A data key that another run moved first: the compare-and-set fails and nothing is counted as moved.
      const [key] = await w.store.list(ORG_A);
      await w.store.replaceWrap(ORG_A, key!.kid, key!.kekId, { kekId: 'elsewhere', wrapped: key!.wrapped });
      const rewrap = new DataKeyRewrapStep(w.store, ringKek(w.newKey, w.oldKey), sameOrg);
      const dry = await rewrap.run({ apply: false, checkpoint: () => undefined, progress: () => undefined });
      expect(dry.unreadable).to.equal(1);
    });
  });
});
